// ============ VIDEO ============
// Lägg till en video för en övning genom att sätta `video: "..."` på dess
// DIAGRAMS-post ovan, t.ex:
//   Tunnelkull: { video: "https://youtu.be/XXXXXXXX", caption: "...", svg: (...) }
// Stödjer YouTube-länkar, Vimeo-länkar, eller en direkt videofil (.mp4/.webm/.mov,
// t.ex. en fil du lagt i /public/videos/tunnelkull.mp4 och länkat som "/videos/tunnelkull.mp4").
// Om ingen video är satt visas SVG-diagrammet som vanligt.

function getYouTubeId(url) {
  const m = url.match(
    /(?:youtube\.com\/(?:watch\?v=|shorts\/|embed\/)|youtu\.be\/)([A-Za-z0-9_-]{6,})/
  );
  return m ? m[1] : null;
}

function getVimeoId(url) {
  const m = url.match(/vimeo\.com\/(?:video\/)?(\d+)/);
  return m ? m[1] : null;
}

function isDirectVideoFile(url) {
  return /\.(mp4|webm|mov|m4v)(\?.*)?$/i.test(url);
}

// Visar övningens video om en sådan finns, annars faller tillbaka på SVG-diagrammet.
function ExerciseMedia({ diagram }) {
  const url = diagram?.video;

  if (url) {
    const ytId = getYouTubeId(url);
    const vimeoId = getVimeoId(url);

    if (ytId) {
      return (
        <div
          className="rounded-lg overflow-hidden"
          style={{ position: "relative", width: "100%", paddingTop: "56.25%", background: "#000" }}
        >
          <iframe
            src={`https://www.youtube-nocookie.com/embed/${ytId}`}
            title={diagram.caption || "Övningsvideo"}
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
            allowFullScreen
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", border: 0 }}
          />
        </div>
      );
    }

    if (vimeoId) {
      return (
        <div
          className="rounded-lg overflow-hidden"
          style={{ position: "relative", width: "100%", paddingTop: "56.25%", background: "#000" }}
        >
          <iframe
            src={`https://player.vimeo.com/video/${vimeoId}`}
            title={diagram.caption || "Övningsvideo"}
            allow="autoplay; fullscreen; picture-in-picture"
            allowFullScreen
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", border: 0 }}
          />
        </div>
      );
    }

    if (isDirectVideoFile(url)) {
      return (
        <video
          controls
          playsInline
          preload="metadata"
          className="w-full rounded-lg"
          style={{ background: "#000", display: "block" }}
        >
          <source src={url} />
          Din webbläsare kan inte spela upp videon.
        </video>
      );
    }
  }

  // Ingen video (eller okänt videoformat) — visa SVG-diagrammet som vanligt.
  return diagram?.svg || null;
}

// Ritar N mini-spelplaner sida vid sida med angivet format (t.ex. "3v3").
function PitchDiagram({ count, format, configs }) {
  const pitchW = 150;
  const pitchH = 100;
  const gap = 14;

  // Om configs skickas in används de (t.ex. olika antal mål per plan).
  // Annars byggs en enhetlig lista utifrån count/format.
  const pitches = configs || Array.from({ length: count }, () => ({ format, goalsPerSide: 1 }));

  const renderGoals = (offsetX, side, goalsPerSide) => {
    const goalH = 18;
    const spacing = pitchH / (goalsPerSide + 1);
    return Array.from({ length: goalsPerSide }, (_, gi) => {
      const y = spacing * (gi + 1) - goalH / 2;
      const x = side === "left" ? offsetX - 3 : offsetX + pitchW - 3;
      return <rect key={side + gi} x={x} y={y} width="6" height={goalH} fill="#146C93" rx="1" />;
    });
  };

  const renderPitch = (offsetX, config, idx) => {
    const perTeam = parseInt((config.format.match(/\d+/g) || [3])[0], 10);
    const goalsPerSide = config.goalsPerSide || 1;
    const darkPositions = Array.from({ length: perTeam }, (_, k) => ({
      x: offsetX + 20 + (k % 2) * 14,
      y: 20 + k * ((pitchH - 40) / Math.max(perTeam - 1, 1)),
    }));
    const redPositions = Array.from({ length: perTeam }, (_, k) => ({
      x: offsetX + pitchW - 20 - (k % 2) * 14,
      y: 20 + k * ((pitchH - 40) / Math.max(perTeam - 1, 1)),
    }));
    return (
      <g key={idx}>
        <rect
          x={offsetX}
          y={0}
          width={pitchW}
          height={pitchH}
          rx="8"
          fill="#E6E9ED"
          stroke="#C3C9CF"
          strokeWidth="2"
        />
        {/* mittlinje */}
        <line x1={offsetX + pitchW / 2} y1={4} x2={offsetX + pitchW / 2} y2={pitchH - 4} stroke="#C3C9CF" strokeWidth="1.5" strokeDasharray="3 3" />
        {/* mål */}
        {renderGoals(offsetX, "left", goalsPerSide)}
        {renderGoals(offsetX, "right", goalsPerSide)}
        {darkPositions.map((p, i) => (
          <circle key={"d" + i} cx={p.x} cy={p.y} r="6.5" fill="#262A2E" />
        ))}
        {redPositions.map((p, i) => (
          <circle key={"r" + i} cx={p.x} cy={p.y} r="6.5" fill="#28A9E2" />
        ))}
      </g>
    );
  };

  const totalW = pitches.length * pitchW + (pitches.length - 1) * gap;

  return (
    <svg viewBox={`0 0 ${totalW} ${pitchH}`} className="w-full h-auto">
      {pitches.map((cfg, i) => renderPitch(i * (pitchW + gap), cfg, i))}
    </svg>
  );
}

// Visar en yta där spelare driver runt med varsin boll, med pilar som antyder rörelse.
function DribbleAreaDiagram() {
  const players = [
    { x: 55, y: 45, angle: 20 },
    { x: 140, y: 30, angle: -35 },
    { x: 220, y: 55, angle: 60 },
    { x: 90, y: 110, angle: -60 },
    { x: 180, y: 130, angle: 15 },
    { x: 250, y: 105, angle: -20 },
  ];

  return (
    <svg viewBox="0 0 300 170" className="w-full h-auto">
      <rect x="8" y="8" width="284" height="154" rx="14" fill="#E6E9ED" stroke="#C3C9CF" strokeWidth="2" strokeDasharray="6 6" />
      {players.map((p, i) => {
        const rad = (p.angle * Math.PI) / 180;
        const ax = p.x + Math.cos(rad) * 22;
        const ay = p.y + Math.sin(rad) * 22;
        return (
          <g key={i}>
            <path
              d={`M${p.x} ${p.y} L${ax} ${ay}`}
              stroke="#146C93"
              strokeWidth="2"
              strokeDasharray="3 3"
              markerEnd="url(#dribArrow)"
            />
            <circle cx={p.x} cy={p.y} r="8" fill="#262A2E" />
            <circle
              cx={p.x + Math.cos(rad) * 13}
              cy={p.y + Math.sin(rad) * 13}
              r="4"
              fill="#28A9E2"
            />
          </g>
        );
      })}
      <defs>
        <marker id="dribArrow" markerWidth="7" markerHeight="7" refX="3.5" refY="3.5" orient="auto">
          <path d="M0,0 L7,3.5 L0,7 z" fill="#146C93" />
        </marker>
      </defs>
    </svg>
  );
}

